private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int b1 = bb.get(i) & 0xFF;
    if ((b1 & 0x80) == 0) {
        sb.append((char) b1);
        return i + 1;
    }
    if ((b1 & 0xE0) == 0xC0) {
        int b2 = bb.get(i + 1) & 0x3F;
        int cp = ((b1 & 0x1F) << 6) | b2;
        sb.append((char) cp);
        return i + 2;
    }
    if ((b1 & 0xF0) == 0xE0) {
        int b2 = bb.get(i + 1) & 0x3F;
        int b3 = bb.get(i + 2) & 0x3F;
        int cp = ((b1 & 0x0F) << 12) | (b2 << 6) | b3;
        sb.append((char) cp);
        return i + 3;
    }
    if ((b1 & 0xF8) == 0xF0) {
        int b2 = bb.get(i + 1) & 0x3F;
        int b3 = bb.get(i + 2) & 0x3F;
        int b4 = bb.get(i + 3) & 0x3F;
        int cp = ((b1 & 0x07) << 18) | (b2 << 12) | (b3 << 6) | b4;
        cp -= 0x10000;
