public long contentLength(){
    // Attempt to retrieve the content length from the request.
    // If the request object is not available, return -1 to indicate unknown length.
    if (request == null) {
        return -1L;
    }

    // Prefer the servlet API's getContentLengthLong() if available.
    long len = request.getContentLengthLong();
    if (len >= 0) {
        return len;
    }

    // Fallback: parse the "Content-Length" header manually.
    String header = request.getHeader("Content-Length");
    if (header != null) {
        try {
            return Long.parseLong(header);
        } catch (NumberFormatException e) {
            // Header was present but not a valid number; fall through.
        }
    }

    // If all else fails, indicate that the length is unknown.
    return -1L;
}

