@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Define sizes of the two partitions
    int sizeA = 3;
    int sizeB = 3;

    // Lists to hold vertices of each partition
    List<V> partitionA = new ArrayList<>();
    List<V> partitionB = new ArrayList<>();

    // Create vertices for partition A
    for (int i = 1; i <= sizeA; i++) {
        @SuppressWarnings("unchecked")
        V vertex = (V) ("A" + i);
        target.addVertex(vertex);
        partitionA.add(vertex);
        resultMap.put("A" + i, vertex);
    }

    // Create vertices for partition B
    for (int i = 1; i <= sizeB; i++) {
        @SuppressWarnings("unchecked")
        V vertex = (V) ("B" + i);
        target.addVertex(vertex);
        partitionB.add(vertex);
        resultMap.put("B" + i, vertex);
    }

    // Add edges between every vertex in partition A and every vertex in partition B
    for (V a : partitionA) {
        for (V b : partitionB) {
            target.addEdge(a, b);
        }
    }
}

