public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Compute the serialized size of the message
    int size = schema.getSerializedSize(message);

    // Write the length prefix as a varint to the output stream
    CodedOutputStream lengthOut = CodedOutputStream.newInstance(out);
    lengthOut.writeRawVarint32(size);
    lengthOut.flush();

    // Serialize the message into the provided buffer
    CodedOutputStream bufferOut = CodedOutputStream.newInstance(buffer);
    schema.writeTo(message, bufferOut);
    bufferOut.flush();

    // Write the buffered bytes to the output stream
    out.write(buffer.toByteArray());

    return size;
}

