public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pType = (ParameterizedType) genericType;
    Type[] args = pType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    Map<TypeVariable<?>, Type> typeVarAssigns = buildTypeVariableAssignments(targetType);
    for (int i = 0; i < args.length; i++) {
        Class<?> resolved = resolveType(args[i], typeVarAssigns);
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
}

private static Map<TypeVariable<?>, Type> buildTypeVariableAssignments(Class<?> targetType) {
    Map<TypeVariable<?>, Type> map = new java.util.HashMap<>();
    java.util.Set<Type> visited = new java.util.HashSet<>();
    processType(targetType.getGenericSuperclass(), map, visited);
    for (Type iface : targetType.getGenericInterfaces()) {
        processType(iface, map, visited);
    }
    return map;
}

private static void processType(Type type, Map<TypeVariable<?>, Type> map, java.util.Set<Type> visited) {
    if (type == null || visited.contains(type)) {
        return;
    }
    visited.add(type);
    if (type instanceof ParameterizedType) {
        ParameterizedType p = (ParameterizedType) type;
        Type raw = p.getRawType();
        if (raw instanceof Class) {
            Class<?> rawClass = (Class<?>) raw;
            TypeVariable<?>[] vars = rawClass.getTypeParameters();
            Type[] args = p.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                map.put(vars[i], args[i]);
            }
            processType(rawClass.getGenericSuperclass(), map, visited);
            for (Type iface : rawClass.getGenericInterfaces()) {
                processType(iface, map, visited);
            }
        }
    } else if (type instanceof Class) {
        Class<?> cls = (Class<?>) type;
        processType(cls.getGenericSuperclass(), map, visited);
        for (Type iface : cls.getGenericInterfaces()) {
            processType(iface, map, visited);
        }
    }
}

private static Class<?> resolveType(Type type, Map<TypeVariable<?>, Type> map) {
    if (type instanceof Class) {
        return (Class<?>) type;
    } else if (type instanceof TypeVariable) {
        Type resolved = map.get(type);
        if (resolved == null) {
            return null;
        }
        if (resolved instanceof Class) {
            return (Class<?>) resolved;
        } else if (resolved instanceof ParameterizedType) {
            return (Class<?>) ((ParameterizedType) resolved).getRawType();
        } else if (resolved instanceof TypeVariable) {
            return resolveType(resolved, map);
        } else {
            return null;
        }
    } else if (type instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) type).getRawType();
    } else if (type instanceof GenericArrayType) {
        Type comp = ((GenericArrayType) type).getGenericComponentType();
        Class<?> compClass = resolveType(comp, map);
        if (compClass != null) {
            return java.lang.reflect.Array.newInstance(compClass, 0).getClass();
        }
        return null;
    } else {
        return null;
    }
}

