public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        // Retrieve the current index mapping from Elasticsearch
        GetMappingsRequest request = new GetMappingsRequest().indices(tableName);
        GetMappingsResponse response = client.indices().getMapping(request, RequestOptions.DEFAULT);
        Map<String, Object> currentMap = response.mappings().get(tableName).getSourceAsMap();

        // Retrieve the history mapping that was passed in
        Map<String, Object> historyMap = mappings.getSourceAsMap();

        // Extract the properties section from both mappings
        Map<String, Object> currentProps = (Map<String, Object>) currentMap.get("properties");
        Map<String, Object> historyProps = (Map<String, Object>) historyMap.get("properties");

        // Compute the diff: fields present in current but not in history
        Map<String, Object> diffProps = new HashMap<>();
        if (currentProps != null) {
            for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
                String field = entry.getKey();
                // Skip the _source configuration to avoid update conflicts
                if ("_source".equals(field)) {
                    continue;
                }
                if (historyProps == null || !historyProps.containsKey(field)) {
                    diffProps.put(field, entry.getValue());
                }
            }
        }

        // Build the resulting mapping
        Map<String, Object> diffMap = new HashMap<>();
        if (!diffProps.isEmpty()) {
            diffMap.put("properties", diffProps);
        }

        return new Mappings(diffMap);
    } catch (IOException e) {
        throw new RuntimeException("Failed to compute mapping diff for table: " + tableName, e);
    }
}

