static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("index=" + index + ", len=" + len + ", str.length()=" + str.length());
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else {
            if (Character.isHighSurrogate(ch)) {
                if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                    size += 4;
                    i++; // skip low surrogate
                } else {
                    // malformed surrogate pair, encode as 3 bytes
                    size += 3;
                }
            } else if (Character.isLowSurrogate(ch)) {
                // lone low surrogate, encode as 3 bytes
                size += 3;
            } else {
                size += 3;
            }
        }
    }
    return size;
}

