        return this;
    }
    int newLength = this.length + byteLength;
    if(this.data == null || newLength > this.data.length){
        int newCapacity = this.data == null ? byteLength : this.data.length * 2;
        if(newCapacity < newLength){
            newCapacity = newLength;
        }
        byte[] newData = new byte[newCapacity];
        if(this.data != null){
