public void removeFromTreeEdgeList(){
    // Remove from the first doubly linked list of tree edges
    if (prevTreeEdge != null) {
        prevTreeEdge.nextTreeEdge = nextTreeEdge;
    }
    if (nextTreeEdge != null) {
        nextTreeEdge.prevTreeEdge = prevTreeEdge;
    }
    // Remove from the second doubly linked list of tree edges
    if (prevTreeEdgeOpposite != null) {
        prevTreeEdgeOpposite.nextTreeEdgeOpposite = nextTreeEdgeOpposite;
    }
    if (nextTreeEdgeOpposite != null) {
        nextTreeEdgeOpposite.prevTreeEdgeOpposite = prevTreeEdgeOpposite;
    }
    // Nullify this edge's own pointers
    prevTreeEdge = nextTreeEdge = prevTreeEdgeOpposite = nextTreeEdgeOpposite = null;
}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Pattern to find ${var} placeholders
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    // Limit recursion depth to avoid infinite loops
    int maxDepth = 10;
    int depth = 0;
    String result = value;
    while (depth < maxDepth) {
        java.util.regex.Matcher matcher = pattern.matcher(result);
        boolean found = false;
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            found = true;
            String varName = matcher.group(1);
            String varValue = props.getProperty(varName);
            if (varValue == null) {
                // If variable not found, keep placeholder unchanged
                varValue = matcher.group(0);
            }
            matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(varValue));
        }
        matcher.appendTail(sb);
        result = sb.toString();
        if (!found) {
            break;
        }
        depth++;
    }
    return result;
}

