public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return new ArrayList<>();
    }
    boolean isAbsolute = rawPath.startsWith("/");
    String[] parts = rawPath.split("/", -1);
    List<PathSegmentImpl> segments = new ArrayList<>();
    int start = isAbsolute ? 1 : 0;
    for (int i = start; i < parts.length; i++) {
        String rawSegment = parts[i];
        String decodedSegment = rawSegment;
        if (decode) {
            try {
                decodedSegment = java.net.URLDecoder.decode(rawSegment, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                // If decoding fails, keep the raw segment
            }
        }
        segments.add(new PathSegmentImpl(rawSegment, decodedSegment));
    }
    return segments;
}

