@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or primitive char
    if (!Character.class.equals(type) && !char.class.equals(type)) {
        throw new IllegalArgumentException("Target type must be Character or char");
    }

    // Null values are returned as null
    if (value == null) {
        return null;
    }

    // If already a Character, return it directly
    if (value instanceof Character) {
        return value;
    }

    // If the value is a String, it must be a single character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert String of length " + str.length() + " to Character");
        }
    }

    // If the value is a Number, cast its int value to a char
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }

    // For any other type, attempt to use its string representation
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }

    throw new IllegalArgumentException("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

