final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // helper to read unsigned short from classFileBuffer
    final int readUnsignedShort(int pos){
        return ((classFileBuffer[pos] & 0xFF) << 8) | (classFileBuffer[pos+1] & 0xFF);
    }
    // constant_pool_count is at offset 8 (u2)
    final int cpCount = readUnsignedShort(8);
    if (constantPoolEntryIndex <= 0 || constantPoolEntryIndex >= cpCount) {
        throw new IllegalArgumentException("Invalid constant pool index: " + constantPoolEntryIndex);
    }
    // start of constant pool entries
    int offset = 10;
    // iterate to the target entry
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        int tag = classFileBuffer[offset] & 0xFF;
        offset++;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int len = readUnsignedShort(offset);
                offset += 2 + len;
                break;
            case 3: // CONSTANT_Integer
            case 4: // CONSTANT_Float
                offset += 4;
                break;
            case 5: // CONSTANT_Long
            case 6: // CONSTANT_Double
                offset += 8;
                i++; // these take up two entries
                break;
            case 7: // CONSTANT_Class
            case 8: // CONSTANT_String
                offset += 2;
                break;
            case 9: // CONSTANT_Fieldref
            case 10: // CONSTANT_Methodref
            case 11: // CONSTANT_InterfaceMethodref
            case 12: // CONSTANT_NameAndType
                offset += 4;
                break;
            case 15: // CONSTANT_MethodHandle
                offset += 3;
                break;
            case 16: // CONSTANT_MethodType
                offset += 2;
                break;
            case 18: // CONSTANT_InvokeDynamic
                offset += 4;
                break;
            default:
                throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
        }
    }
    // now offset points to the tag of the target entry
    int tag = classFileBuffer[offset] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Constant pool entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
    }
    offset++; // skip tag
    int len = readUnsignedShort(offset);
    offset += 2;
    if (len > charBuffer.length) {
        throw new IllegalArgumentException("Provided charBuffer is too small for UTF-8 string of length " + len);
    }
    // decode UTF-8 bytes into charBuffer
    new String(classFileBuffer, offset, len, "UTF-8").getChars(0, len, charBuffer, 0);
    return new String(charBuffer, 0, len);
}

private static char decodeHexNibble(final char c){
