        int newCap = Math.max(buffer.length * 2, newLength);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buffer, 0, newBuf, 0, length);
        buffer = newBuf;
    }
    if (byteArrayValue == null) {
        java.util.Arrays.fill(buffer, length, newLength, (byte) 0);
    } else {
        System.arraycopy(byteArrayValue, byteOffset, buffer, length, byteLength);
    }
    length = newLength;
    return this;
}

