protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if(tour==null || tour.isEmpty()){
        return null;
    }
    // Directed graph handling
    if(graph.isDirected()){
        Map<V, List<E>> outAdj = new HashMap<>();
        for(E e : tour){
            V src = graph.getEdgeSource(e);
            outAdj.computeIfAbsent(src, k->new ArrayList<>()).add(e);
        }
        V start = outAdj.keySet().iterator().next();
        List<V> vertexList = new ArrayList<>();
        List<E> edgeList = new ArrayList<>();
        Set<E> visited = new HashSet<>();
        V current = start;
        while(true){
            vertexList.add(current);
            List<E> edges = outAdj.get(current);
            if(edges==null || edges.isEmpty()){
                break;
            }
            E nextEdge = null;
            for(E e : edges){
                if(!visited.contains(e)){
                    nextEdge = e;
                    break;
                }
            }
            if(nextEdge==null){
                break;
            }
            edgeList.add(nextEdge);
            visited.add(nextEdge);
            current = graph.getEdgeTarget(nextEdge);
            if(current.equals(start)){
                vertexList.add(current);
                break;
            }
        }
        double weight = 0.0;
        for(E e : edgeList){
            weight += graph.getEdgeWeight(e);
        }
        return new DefaultGraphPath<>(graph, start, current, vertexList, edgeList, weight);
    }
    // Undirected graph handling
    Map<V, List<E>> adj = new HashMap<>();
    for(E e : tour){
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adj.computeIfAbsent(u, k->new ArrayList<>()).add(e);
        adj.computeIfAbsent(v, k->new ArrayList<>()).add(e);
    }
    V start = adj.keySet().iterator().next();
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> visited = new HashSet<>();
    V current = start;
    V prev = null;
    while(true){
        vertexList.add(current);
        List<E> edges = adj.get(current);
        if(edges==null || edges.isEmpty()){
            break;
        }
        E nextEdge = null;
        for(E e : edges){
            if(!visited.contains(e)){
                nextEdge = e;
                break;
            }
        }
        if(nextEdge==null){
            break;
        }
        edgeList.add(nextEdge);
        visited.add(nextEdge);
        V next = graph.getEdgeSource(nextEdge).equals(current) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        prev = current;
        current = next;
        if(current.equals(start)){
            vertexList.add(current);
            break;
        }
    }
    double weight = 0.0;
    for(E e : edgeList){
        weight += graph.getEdgeWeight(e);
    }
    return new DefaultGraphPath<>(graph, start, current, vertexList, edgeList, weight);
}

