int addConstantNameAndType(final String name, final String descriptor){
    // Use a unique key for the name/descriptor pair
    String key = name + '\0' + descriptor;
    // Check if we already have this entry
    Integer existing = nameAndTypeMap.get(key);
    if (existing != null) {
        return existing;
    }
    // Add the name and descriptor as UTF‑8 constants
    int nameIndex = addConstantUtf8(name);
    int descriptorIndex = addConstantUtf8(descriptor);
    // Create the NameAndType constant pool entry (tag 12)
    ConstantPoolInfo info = new ConstantPoolInfo((byte)12, nameIndex, descriptorIndex);
    // Append to the pool and record its index
    int index = constantPool.size();
    constantPool.add(info);
    nameAndTypeMap.put(key, index);
    return index;
}

private String unescapeId(String input) {
