private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }
    List<Integer> suffix = new ArrayList<>(bounds.size());
    long total = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        total += bounds.get(i);
        suffix.add(0, (int) total);
    }
    return new Pair<>(suffix, total);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        return;
    }
    int n = arr.length;
    if (from < 0) {
        from = 0;
    }
    if (to >= n) {
        to = n - 1;
    }
    if (from >= to) {
        return;
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Lock both lists to ensure the move is atomic
    synchronized (this) {
        synchronized (list) {
            // Continuously move the first node from the source list to this list
            ListNodeImpl<E> node = list.getHead();
            while (node != null) {
                // Detach the node from the source list
                list.removeListNode(node);
                // Attach the node to this list
                this.addListNode(node);
                // Get the new first node from the source list
                node = list.getHead();
            }
        }
    }
}

