public ByteVector putInt(final int intValue){
    int pos = this.pos;
    int cap = this.cap;
    byte[] buf = this.buf;
    if (pos + 4 > cap) {
        int newCap = Math.max(cap << 1, pos + 4);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buf, 0, newBuf, 0, pos);
        this.buf = newBuf;
        this.cap = newCap;
        buf = newBuf;
    }
    buf[pos++] = (byte)(intValue >> 24);
    buf[pos++] = (byte)(intValue >> 16);
    buf[pos++] = (byte)(intValue >> 8);
    buf[pos++] = (byte)intValue;
    this.pos = pos;
    return this;
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    if (a == b) {
        return true;
    }
    if (a == null || b == null) {
        return false;
    }
    if (count < 0) {
        throw new IllegalArgumentException("count must be non-negative");
    }
    if (count > a.length || count > b.length) {
        throw new ArrayIndexOutOfBoundsException("count exceeds array length");
    }
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    if (name == null) return;
    int len = name.length();
    if (nameStart < 0) nameStart = 0;
    if (nameStart >= len) return;
    boolean startOfWord = true;
    for (int i = nameStart; i < len; i++) {
        char c = name.charAt(i);
        if (Character.isWhitespace(c)) {
            startOfWord = true;
        } else {
            if (startOfWord) {
                buf.append(Character.toUpperCase(c));
                buf.append('.');
                startOfWord = false;
            }
        }
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable){
    if (typeVariable == null) {
        return Unknown.class;
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }
    Type bound = bounds[0];
    if (bound instanceof Class && bound == Object.class) {
        return Unknown.class;
    }
    return bound;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // A set with 0 or 1 vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    // Check every unordered pair of distinct vertices
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

