}

private void pop(final String descriptor) {
    int i = 0;
    int len = descriptor.length();
    if (len == 0) {
        return;
    }
    if (descriptor.charAt(0) == '(') {
        // Method descriptor: pop argument types
        i++; // skip '('
        while (i < len && descriptor.charAt(i) != ')') {
            // Parse a single type descriptor
            while (i < len && descriptor.charAt(i) == '[') {
                i++; // consume array brackets
            }
            if (i >= len) {
                break;
            }
            char c = descriptor.charAt(i);
            if (c == 'L') {
                // Object type: consume until ';'
                i++; // skip 'L'
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i < len) {
                    i++; // skip ';'
                }
            } else {
                // Primitive type: single character
                i++;
            }
            // Pop one type from the output frame stack
            if (!outputFrameStack.isEmpty()) {
                outputFrameStack.remove(outputFrameStack.size() - 1);
            }
        }
        // Skip the closing ')'
        // The return type is ignored for popping
    } else {
        // Single type descriptor: pop it
        while (i < len && descriptor.charAt(i) == '[') {
            i++; // consume array brackets
        }
        if (i < len) {
            char c = descriptor.charAt(i);
            if (c == 'L') {
                // Object type: consume until ';'
                i++; // skip 'L'
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i < len) {
                    i++; // skip ';'
                }
            } else {
                // Primitive type: single character
                i++;
            }
            // Pop one type from the output frame stack
            if (!outputFrameStack.isEmpty()) {
                outputFrameStack.remove(outputFrameStack.size() - 1);
            }
        }
    }
}

