private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        int boundIndex = -1;
        for (int j = i + 1; j < keys.size(); j++) {
            K candidate = keys.get(j);
            if (!(candidate instanceof Comparable)) {
                throw new IllegalArgumentException("Key type must implement Comparable");
            }
            if (((Comparable) candidate).compareTo(key) > 0) {
                boundIndex = j;
                break;
            }
        }
        bounds.add(boundIndex);
    }
    return bounds;
}

