static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int nonNullCount = 0;
    for (Object o : array) {
        if (o != null) {
            nonNullCount++;
        }
    }
    if (nonNullCount == array.length) {
        return (String[]) array;
    }
    String[] result = new String[nonNullCount];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            result[idx++] = (String) o;
        }
    }
    return result;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    // Find the last path separator (Unix '/' or Windows '\\')
    int lastSeparator = Math.max(filename.lastIndexOf('/'), filename.lastIndexOf('\\'));
    // Find the last dot in the filename
    int lastDot = filename.lastIndexOf('.');
    // If there is no dot or the dot comes after the last separator, no extension
    if (lastDot == -1 || lastDot < lastSeparator) {
        return -1;
    }
    return lastDot;
}

